// Generated by the platform from the OpenAPI contract (ADR-0016). Do not edit: it follows the design (C3).

import { call } from './client-runtime'
export { ApiError } from './client-runtime'

export interface SimulateConsumerLoanRequest {
  /** decimal(12,2,signed) */
  monto: number
  /** integer(32,signed) */
  plazo: number
}

export interface SimulateConsumerLoanResponse {
  /** decimal(5,2,signed) */
  tasaAnual: number
  /** decimal(12,2,signed) */
  cuotaMensual: number
  /** decimal(14,2,signed) */
  totalAPagar: number
}

export interface Api {
  /** Validates the amount (1000.00 to 50000.00) and the term (6 to 60 whole months), determines the annual rate from the term bracket, calculates the monthly installment with the French system (rounded to 2 decimals, half up) and the total to pay (installment x term). It then saves the accepted simulation for audit with a correlative number and timestamp. A rejected simulation is never saved. Called by the Simulador screen action 'calcular'; the result is shown on the Resultado screen. (rules RULE-001, RULE-002, RULE-003, RULE-004, RULE-005, RULE-006) */
  simulateConsumerLoan(request: SimulateConsumerLoanRequest): Promise<SimulateConsumerLoanResponse>
}

/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */
export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init)): Api {
  return {
    simulateConsumerLoan: (request) => call<SimulateConsumerLoanResponse>(fetchImpl, baseUrl, 'POST', '/api/loansimulation/simulations', request, true),
  }
}
